LG = {3.5,4.5,4.5,4.5,4.5,4,4.5,4.5,3,1.5,3}
function layout(txt, cx, s)
  local tot = 0
  for i=1,#txt do tot = tot + LW[txt:sub(i,i)]*s if i<#txt then tot = tot + LG[i]*s end end
  local xs, x = {}, cx - tot/2
  for i=1,#txt do xs[i]=x x = x + LW[txt:sub(i,i)]*s + (LG[i] or 0)*s end
  return xs, tot
end
